void PageHandlerAsyncWaiter::GetReadLaterEntries(
    ReadLaterEntriesByStatusPtr* out_entries) {
  base::RunLoop loop;
  proxy_->GetReadLaterEntries(
      base::BindOnce(
          [](base::RunLoop* loop,
             ReadLaterEntriesByStatusPtr* out_entries
,
             ReadLaterEntriesByStatusPtr entries) {*out_entries = std::move(entries);
            loop->Quit();
          },
          &loop,
          out_entries));
  loop.Run();
}

